import { useId, useRef, useState, type KeyboardEvent } from 'react';
import { JxButton } from '@jinx-ui/react';

// NB: only JxButton is confirmed by the package README. The `jx-field` / `jx-input` /
// `jx-tag` classes and `--jx-space-*` tokens follow the documented `jx-*` CSS contract
// but should be checked against the installed @jinx-ui/core build before merging.

type ArticleTagPickerProps = {
  label?: string;
  placeholder?: string;
  defaultValue?: string[];
  onChange: (tags: string[]) => void;
};

export default function ArticleTagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  defaultValue = [],
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultValue);
  const [draft, setDraft] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  const inputId = useId();
  const hintId = useId();

  const commit = (next: string[]) => {
    setTags(next);
    onChange(next);
  };

  const addTag = (raw: string) => {
    const tag = raw.trim().replace(/,+$/, '').trim();
    if (!tag || tags.some((t) => t.toLowerCase() === tag.toLowerCase())) {
      setDraft('');
      return;
    }
    commit([...tags, tag]);
    setDraft('');
  };

  const removeTag = (tag: string) => {
    commit(tags.filter((t) => t !== tag));
    inputRef.current?.focus();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag(draft);
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      event.preventDefault();
      removeTag(tags[tags.length - 1]);
    }
  };

  return (
    <div
      className="jx-field"
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}
    >
      <label className="jx-label" htmlFor={inputId}>
        {label}
      </label>

      <input
        id={inputId}
        ref={inputRef}
        className="jx-input"
        type="text"
        autoComplete="off"
        value={draft}
        placeholder={placeholder}
        aria-describedby={hintId}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={() => addTag(draft)}
      />

      <span id={hintId} className="jx-hint">
        Enter или запятая — добавить тег, Backspace — удалить последний
      </span>

      {tags.length > 0 && (
        <ul
          aria-label="Выбранные теги"
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            gap: 'var(--jx-space-2)',
            margin: 0,
            padding: 0,
            listStyle: 'none',
          }}
        >
          {tags.map((tag) => (
            <li
              key={tag}
              className="jx-tag"
              style={{ display: 'inline-flex', alignItems: 'center', gap: 'var(--jx-space-1)' }}
            >
              <span>{tag}</span>
              <JxButton aria-label={`Удалить тег ${tag}`} onClick={() => removeTag(tag)}>
                ×
              </JxButton>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

